mapper.select:
SELECT DISTINCT a.* FROM article a INNER JOIN article_tag at ON at.article_id = a.id WHERE at.tag_id IN
#{tagId}
AND a.status = 1 AND a.is_deleted = 0 ORDER BY a.create_time DESC, a.id DESC LIMIT #{limit}

SELECT a.* FROM article a WHERE a.id IN
#{articleId}
AND a.status = 1 AND a.is_deleted = 0
